type Run={interfaces:string[];fixture:string;scope:string;check:(a:typeof assert)=>unknown|Promise<unknown>}
const adapters:Record<string,Run>={}
const bind=(id:string,interfaces:string[],fixture:string,scope:string,check:Run['check'])=>{adapters[id]={interfaces,fixture,scope,check}}
const num=(a:typeof assert,actual:number|null|undefined,expected:number)=>{a.equal(typeof actual,'number');a.ok(Number.isFinite(actual));a.ok(Math.abs(actual!-expected)<1e-8,`${actual} != ${expected}`)}
const row=(id:string,value:number|null=30,extra:Partial<EvolutionEvidence>={}):EvolutionEvidence=>({id,athleteId:A,occurrenceId:'s1',metric:'SPLIT_SECONDS',value,unit:'s',context:'running:main:rep:b:step:1:1:200m',eventAt:EVENT,recordedAt:EVENT,source:'TRAINING_FACT',sourceId:'fact:'+id,confirmation:'CONFIRMED',measurement:{method:'HAND_STOPWATCH_SAME_START',segmentSourceId:'fact:'+id},...extra})
const rows=(seconds:(number|null)[],occ='s1',date='2026-10-18')=>seconds.map((n,i)=>row(`${occ}-${i}`,n,{occurrenceId:occ,context:`running:main:rep:b:step:1:${i+1}:200m`,eventAt:date+'T10:00:00Z',recordedAt:date+'T11:00:00Z'}))
const rest=(occ:string,date='2026-10-18',n=120)=>row(`${occ}-rest`,n,{occurrenceId:occ,metric:'REST_SECONDS',context:'rest1',unit:'s',eventAt:date+'T10:00:00Z',recordedAt:date+'T11:00:00Z'})
