const device=(distance=0.8):DecodedDeviceActivity=>({sourceFileHash:'synthetic-file-sha',activityId:'synthetic-device-activity',sourceId:'synthetic:device',athleteId:A,identityConfirmed:true,deviceId:'device-A',protocolKey:'A-RMSSD-v1',sport:'RUNNING',startedAt:EVENT,recordedAt:EVENT,totalDistanceMeters:distance*1000,timerSeconds:120,elapsedSeconds:120,expectedLapOrdinals:[1],reportedRests:[],occurrenceBinding:null,laps:[{id:'lap-1',ordinal:1,sourceId:'synthetic:lap1',kind:'WORK',distance:{value:distance,unit:'km'},timerSeconds:120,elapsedSeconds:120,averageHeartRateBpm:null,maximumHeartRateBpm:null,timingMethod:'DEVICE_LAP',heartRateMethod:null,structure:{componentId:'main',blockId:'b',stepId:'step',round:1,repeat:1,confirmed:true}}]})
